insert into public.spaces (slug, building_slug, name, summary, description, floor, floor_label, noise_level, features, capacity, image_url, image_alt, source, source_url, waitz_id, is_listed)
values
  ('art-architecture-and-engineering-library-floor-2-computing-spaces', 'james-and-anne-duderstadt-center', 'Art, Architecture, and Engineering Library Floor 2 Computing Spaces', 'Connect to an external monitor or work with a group at a VizHub in this mixed seating space.', 'When you arrive on floor 2 of the Duderstadt Center via the central stairs, escalator, or elevator, you’re in the Art, Architecture, and Engineering Library.

Opposite the lobby space, you’ll find an open area on the west side of the floor with high ceilings and some natural light. The space has:

- Tables with dual and widescreen external monitors for individual or group work
- High-tech VizHubs stations
- Cushioned bench seating and a large booth
- Areas partially partitioned by geometric walls

An enclosed area on the far west side of the floor with windows on the interior wall has additional VizHub stations. Some are separated by partitions with whiteboard sections. All VizHubs can be reserved in advance.

When you pass through the doors behind the central stairs that lead up to floor 3 and go toward the southwest corner of the floor, you’ll find more computing with additional external monitor stations and printing. This area has lower ceilings and exterior windows.', 2, 'Floor 2', 'conversational'::public.noise_level, '{external_monitors,natural_light,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/aael-computing1_edited_1NJsot.webp', 'Students working individually at a set of tables with external monitors and short privacy dividers..', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/conversational-study-spaces/art-architecture-and-engineering-library-floor-2-computing-spaces', null, true),
  ('art-architecture-and-engineering-library-floor-2-lobby-spaces', 'james-and-anne-duderstadt-center', 'Art, Architecture, and Engineering Library Floor 2 Lobby Spaces', 'Natural light brightens this space with seating at tables amongst a variety of low profile stacks.', 'When you arrive on floor 2 of the Duderstadt Center via the central stairs, escalator, or elevator, you’re in the Art, Architecture, and Engineering Library.

The lobby space is on the north side of the floor. There are high ceilings with tall windows and lots of natural light.

Find a seat among low profile stacks of books and periodicals, or the materials collection. Seating is primarily at tables suitable for small groups or individual work.', 2, 'Floor 2', 'low_noise'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/AAEL-2ndFloorStudy13-Sept2019_fEK4h.webp', 'Aerial view of stacks, seating, and students in the Art, Architecture, and Engineering Library.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/art-architecture-and-engineering-library-floor-2-lobby-spaces', null, true),
  ('art-architecture-and-engineering-library-floor-2-stacks-spaces', 'james-and-anne-duderstadt-center', 'Art, Architecture, and Engineering Library Floor 2 Stacks Spaces', 'Find a quiet spot among the stacks or in a tucked away corner window.', 'When you arrive on floor 2 of the Duderstadt Center via the central stairs, escalator, or elevator, you’re in the Art, Architecture, and Engineering Library.

Pass through the lobby spaces towards the northeast corner of the floor and go through the double doors to find quieter spaces among the book stacks. Natural light comes in from windows on some walls and above the stacks.

Pick from bar-height counter seating along the interior windows, individual desks, or a seat at a large table. Around the perimeter of the space, there’s sets of armchairs around low tables tucked in corners with floor-to-ceiling windows.', 2, 'Floor 2', 'quiet'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/aael-quiet2_edited_1IHi9G.webp', 'Students sitting high-backed wooden chairs at a bar height counter facing windows.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/art-architecture-and-engineering-library-floor-2-stacks-spaces', null, true),
  ('art-architecture-and-engineering-library-floor-3', 'james-and-anne-duderstadt-center', 'Art, Architecture, and Engineering Library Floor 3 Spaces', 'Choose from a variety of seating options, including study pods and large tables.', 'The atmosphere ranges from quiet to conversational on floor 3 of the Duderstadt Center, which is mostly the Art, Architecture, and Engineering Library. Tables among the book stacks are quieter, while those closer to computing areas may have more noise.

There is a variety of seating on this floor including large tables with movable chairs, individual desks, couches, lounge chairs, bar-height counters, and comfortable pods with individually controlled lamps.

The floor also has large computing areas on the outer perimeter of the floor in both the northeast and southwest corners. These include computers and printing as well as areas of “laptop only” stations with extended displays.', 3, 'Floor 3', 'low_noise'::public.noise_level, '{external_monitors,natural_light,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/aael-floor3-3_edited_1Siv0s.webp', 'Students working at a long rectangular table next to book stacks with a whiteboard behind them and windows in the distance.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/art-architecture-and-engineering-library-floor-3', null, true),
  ('asia-library-reading-room', 'harlan-h-hatcher-graduate-library', 'Asia Library Reading Room', 'A mixture of seating and the Oka Tadoku Room make up this cozy, light-filled space in Hatcher North.', 'The Asia Library Reading Room has a few distinct areas in one space: the Oka Tadoku Room, Asia Library Reference Area, and Asia Library Quiet Study Room.

Features include study desks, comfortable booths, and open tables. Lots of natural light fills the space and bookshelves line the walls.

While this is generally a quiet space, there may occasionally be conversation and noise when classes or events are held in the Oka Tadoku Room or Quiet Study Room.', null, null, 'quiet'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Asia%20Libary%20-%20Tadoku%20Reading%20Room_edited_25mqcY.webp', 'Students using seating in the Tadoku Room with laptops and booths in the background', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/asia-library-reading-room', null, true),
  ('berts-study-lounge', 'harold-t-and-vivian-b-shapiro-library', 'Bert''s Study Lounge', 'A café-like atmosphere with mixed seating, good for individual study or group meetings.', 'The Bert’s Study Lounge is next to the Shapiro Lobby Information Services Desk and lined with digital displays on wood-slated and regular walls. It has couches, armchairs and ottomans, a mix of small round tables for 1-2 people, and single-seat bar-height tables.

In addition to the lounge space, there’s a number of regular and bar-height tables in the atrium between the Shapiro entrances.

Bert’s Café is opposite the lounge and a great place to grab a snack.

This is a very high-traffic space where you can expect active noise including talking, café sounds, and people moving around.', null, null, 'conversational'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/berts-study-lounge3_l2Aky.webp', 'Students studying at high and low tables with windows in the background.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/conversational-study-spaces/berts-study-lounge', null, true),
  ('clark-commons-seating-areas', 'harold-t-and-vivian-b-shapiro-library', 'Clark Commons Collaborative Spaces', 'An open and active space with lots of light and a mix of seating options for individual and group study.', 'A variety of seating options are available across the Clark Commons to support individual and group study. The openness of the space lets in natural light no matter where you sit and movable whiteboards are scattered around the floor.', null, null, 'conversational'::public.noise_level, '{all_gender_restroom_on_floor,natural_light,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Clark%20Commons%20Living%20Room%201_edited_kC53F.webp', 'A view of the Clark Commons Living Room with students along counter seating in foreground and seated throughout the space', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/conversational-study-spaces/clark-commons-seating-areas', null, true),
  ('clark-commons-computing-spaces', 'harold-t-and-vivian-b-shapiro-library', 'Clark Commons Computing Spaces', 'Seating areas with a mix of external monitor options, plus a campus computing site.', 'There are 3 different types of computing spaces in the Clark Commons situated among a variety of seating areas.

The first is located outside of the staff space and meeting rooms on the north end of the floor near the central stairs and elevator. There is a bay of extended monitor displays for use with your laptop, along with tables and movable chairs. There are also 2 large screens mounted at tables that you can use with a group.

Outside the Shapiro Reading Room in the southeast corner of the floor, you''ll find a small campus computing site with printing.

Finally, along the perimeter on the east side of the floor, 2 of the collaboration areas have an extended display mounted on the wall for shared screen viewing, along with a table with chairs.', null, null, 'conversational'::public.noise_level, '{all_gender_restroom_on_floor,external_monitors,natural_light,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/clark-commons10_cropped-2_1eGQTb.webp', 'Students working at tables with extended display monitors', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/conversational-study-spaces/clark-commons-computing-spaces', null, true),
  ('clark-library-seating-area', 'harlan-h-hatcher-graduate-library', 'Clark Library Seating Area', 'Couches, armchairs, and tables between windows and exhibit cases.', 'Work in the Clark Library''s seating area by yourself or with a small group. There are sets of couches and armchairs with coffee tables, as well as large tables with movable chairs. The seating runs along south-facing windows with a view of the Clements Library and plenty of natural light.

Expect the sounds of steady traffic with people passing through on their way between Hatcher and Shapiro libraries when you’re studying here. Clark Library Exhibit Space display cases are opposite the main seating area.

There is also counter-height seating and a small number of campus computing site computers along the map cases on the opposite end of the floor.

You can have covered drinks (such as water bottles) in this space, but we don''t allow food to protect the maps and keep the area clean.', null, null, 'low_noise'::public.noise_level, '{external_monitors,natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/clark-library-study1_36nA5.webp', 'Students studying at rectangular tables in comfy chairs alongside windows.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/clark-library-seating-area', null, true),
  ('duderstadt-center-interview-rooms', 'james-and-anne-duderstadt-center', 'Duderstadt Center Interview Rooms', 'Small rooms you can book up to 3 days in advance.', 'Most of these collaboration rooms are designed to accommodate 1–2 people. They each have a table, movable chairs, and a wall-mounted whiteboard.

Book up to 3 days in advance through the Duderstadt Center.

The rooms on floor 2 primarily serve as consultation, group project, and interview spaces booked by CAEN and the School of Engineering. Availability may be limited.', null, null, 'conversational'::public.noise_level, '{bookable}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/duderstadt-interview-room_edited_Z23sF0l.webp', 'Small table with two office chairs and wall-mounted whiteboard.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/duderstadt-center-interview-rooms', null, true),
  ('fine-arts-library-carrels', 'tappan-hall', 'Fine Arts Library Carrels', 'Reserved for graduate students in history of art.', 'History of Art graduate students can reserve a study carrel during the academic year. Great for writing and storing materials needed for your research.

Carrels are assigned by the History of Art Department.', null, null, 'quiet'::public.noise_level, '{bookable,natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/FineArts1-Apr2019_m3vps.webp', 'Student working on their laptop at an open carrel surrounded by stacks of books.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/fine-arts-library-carrels', null, true),
  ('fine-arts-library-floor-2', 'tappan-hall', 'Fine Arts Library Floor 2', 'High ceilings and tables surrounded by books.', 'Enter the Fine Arts Library through the doors on the second floor of Tappan Hall and you’ll find a high-ceiling, book-lined room with large wooden tables and chairs available for studying. There are also some tucked away spots deeper in the library, as well as carrels for graduate students assigned by the History of Art.

Most study spaces are to your left upon entering the library. There are three areas of large wooden tables and chairs that each seat 4-5 people. These areas are separated by a pair of long bookshelves. One is down center alongside a small campus computing site. The other two are on the opposite sides of either book shelf and bordered by large windows for lots of natural light.

Go through the book stacks on floor 2 and you’ll find some rectangular tables with chairs at the ends of the rows. You can also go this way to get to floor 1, where there’s a few more tables and cushioned seating scattered among the shelves.

To keep these spaces clean, you can only have covered drinks and wrapped food.', 2, 'Floor 2', 'quiet'::public.noise_level, '{natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/FineArts2-Apr2019_Z217iQw.webp', 'Open space with windows and students scattered, sitting around large wooden stables.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/fine-arts-library-floor-2', null, true),
  ('hatcher-floor-6', 'harlan-h-hatcher-graduate-library', 'Hatcher Floor 6 Spaces', 'Lounge-like study areas with views of the Law Quad and Michigan Stadium.', 'Take in views of campus from south-facing windows while studying in this quiet space. There are two seating areas on the floor: one within the Special Collections Research Center (SCRC) and another in the open area between the SCRC and book stacks.

In the open space, there are armchairs and low tables, as well as tables with a chair on either side and a divider down the center for privacy. Inside the SCRC, you’ll find tables that seat up to 4 people at movable chairs.

The perimeter of the other half of the floor is lined by bookable weekly carrels and long-term research carrels around the stacks.

The SCRC is not open the full hours of the library building. The study space inside is available Monday through Friday until 5pm.', 6, 'Floor 6', 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Hatcher-SC-StudySpace3-Feb2020_edited_xM5Qx.webp', 'Open space with tables along the windows and a few students studying.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/hatcher-floor-6', null, true),
  ('hatcher-north-212a', 'harlan-h-hatcher-graduate-library', 'Hatcher North 212A', 'Glassed-in space near the center of the floor for solo or small group work.', 'Work alone or collaborate with a small group (up to 5 people) in this glassed-in space. This is an open study area and is not private or soundproof. The walls are transparent and do not reach to the ceiling.

212A is located in the center area of the floor between Hatcher 206 and the entrance to the Hatcher North stacks. The space can be reserved up to 7 days in advance and is open for use when not reserved.

Reserve Hatcher North 212A

See our bookable room guidelines for information about reservation maximums, required check in, and clean up expectations.', null, null, 'conversational'::public.noise_level, '{bookable,external_monitors,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/hatcher%20212a-2_edited_pRiKF.webp', 'Glassed in space along a wall with a table, five chairs, and wall-mounted screen. Computers and entrance to Hatcher South are in the background.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/hatcher-north-212a', null, true),
  ('hatcher-north-floor-2', 'harlan-h-hatcher-graduate-library', 'Hatcher North Floor 2 Spaces', 'An open floor with a range of seating options and regular traffic passing through.', 'The main seating area on floor 2 — located just outside the Hatcher Reference Reading Room — features large wooden tables and colorful chairs. You’ll also find some bar-height seating and clusters of armchairs with side tables.

Serials and Microform Services is on the opposite end of the floor near the main elevators and has a few comfy chairs and small study tables.

As you move towards Hatcher South, the center of the floor is home to:

- Hatcher 206 — a separate room that’s available for studying when not in use for instruction sessions. It has tables, movable chairs, and some armchairs.
- Hatcher North 212A — a bookable, glassed-in space for up to 5 people
- A campus computing site with computers, printers, and flatbed scanners

Since this floor is a primary path to access Hatcher South, you can expect the sounds of steady traffic when you’re studying in the space.', 2, 'Floor 2', 'low_noise'::public.noise_level, '{wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/hatcher-north-floor2-3_Z1S7LME.webp', 'Open, high traffic area with large tables on the side for studying.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/hatcher-north-floor-2', null, true),
  ('hatcher-north-stacks-study-tables', 'harlan-h-hatcher-graduate-library', 'Hatcher North Stacks Study Tables', 'Out-of-the-way spots in the book stacks on 7 different floors.', 'The perimeter of the book stacks in Hatcher North is a treasure trove of study space. All seating is on the south end of each floor and near windows offering plenty of natural light. The windows on the basement floor are slightly smaller since it sits at ground level.

These out-of-the-way locations are well-suited for people studying on their own, or groups doing quiet, focused work.', null, null, 'quiet'::public.noise_level, '{natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Hatcher-BasementStudy1-Apr2019_oRcsy.webp', 'Students sitting at rectangular tables along a wall next to floor-to-ceiling book stacks.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/hatcher-north-stacks-study-tables', null, true),
  ('hatcher-reference-reading-room', 'harlan-h-hatcher-graduate-library', 'Hatcher Reference Reading Room', 'Historic space in Hatcher North that''s well-known for quiet, individual study.', 'The Reference Reading Room is an expansive space on floor 2 of Hatcher North. The room is airy with high vaulted ceilings and tons of natural light from tall windows.

Most seating is at lines of long tables with wooden chairs. Reading lamps divide each table down the center. There are electrical outlets on the underside of the tables for charging.

Bookshelves housing our non-circulating reference collection cover the walls around the room. You’ll find armchairs and side tables tucked near some of them.', null, null, 'quiet'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/hatcher-refroom2-apr2019_ZFiSAB.webp', 'Wide view of the iconic reading room with large windows, students at long tables, and a mural in the distance.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/hatcher-reference-reading-room', null, true),
  ('hatcher-south-bookable-daily-carrels', 'harlan-h-hatcher-graduate-library', 'Hatcher South Bookable Daily Carrels', 'Cubicles for one that can be reserved in advance.', 'Bookable daily carrels are cubicles with a small desk, chair, and window. They do not have doors and are not soundproof.

These spaces are ideal for reading, writing, or any focused work.

We have 92 bookable carrels located around the perimeter of the book stacks on floor 3 of the Hatcher South building.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,bookable,natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/daily-bookable-carrel_1p0aSC.webp', 'Chair and work surface in a study carrel with a window and trees outside, there''s a sign outside the entrance that it''s bookable.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/hatcher-south-bookable-daily-carrels', null, true),
  ('hatcher-south-bookable-weekly-carrels', 'harlan-h-hatcher-graduate-library', 'Hatcher South Bookable Weekly Carrels', 'Donor-furnished cubicles for individual study that can be reserved for up to a week.', 'Our weekly carrels are individual study spaces with a window and donor-funded furnishings, including a desk and chair. These carrels have a door and are for single person use only.

Donor carrels are not soundproof and should only be used for Zoom meetings if you will not be speaking and have headphones or earbuds.

There are 9 of these weekly carrels available in the Hatcher South building. 2 are on floor 4 (a Focus Zone floor) and 7 are on floor 6 near the Special Collections Research Center.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,bookable,natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/bookable%20carrels%20exterior_Z1RVa5a.webp', 'Study carrels with doors, but the walls do not go to the ceiling.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/hatcher-south-bookable-weekly-carrels', null, true),
  ('hatcher-south-designated-ssd-carrels', 'harlan-h-hatcher-graduate-library', 'Hatcher South Designated SSD Carrels', 'Designated, enclosed carrels for Services for Students with Disabilities connected students.', 'We have 4 carrels set aside for use by students connected with Services for Students with Disabilities (SSD). These carrels have doors and some have a window. They contain a small desk and chair. Carrels provide an enclosed space for quiet, focused study.

If you’re eligible, bring your MCard to the Hatcher North information services desk to check out a key.

There are no automatic doors on the floors where these carrels are located and the carrels themselves are not ADA accessible.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/ssd%20carrel_edited_Z1A5k3T.webp', 'Door with Reserved - Office of SSD sign ajar into a room with a chair, desk, and windows with a view of campus.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/hatcher-south-designated-ssd-carrels', null, true),
  ('hatcher-south-long-term-research-carrels', 'harlan-h-hatcher-graduate-library', 'Hatcher South Long-term Research Carrels', 'Semester-long carrel reservations for U-M graduate students and faculty.', 'We have 34 carrels available for semester-long reservations. These carrels have doors and some have a window. They contain a small desk and chair. Reservations are open to U-M graduate students and faculty.

To reserve a long-term research carrel, visit the Hatcher North information services desk. They are in high demand, so you may be put on a waiting list.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,bookable,natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Hatcher-Carrel-Donor-Apr2019_Z1LB8at.webp', 'Close-up of a person sitting at the table in a carrel reading a book.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/hatcher-south-long-term-research-carrels', null, true),
  ('hatcher-south-open-carrels', 'harlan-h-hatcher-graduate-library', 'Hatcher South Open Carrels', 'Cubicles for one with a desk and window.', 'Carrels are cubicles with a small desk, chair, and window. They do not have doors and are not soundproof.

These spaces are ideal for reading, writing, or any focused work.

The carrels are located around the perimeter of the book stacks on floors 4 and 5 of the Hatcher South building.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,natural_light}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/hatcher-south-open-carrels_Zj4KBS.webp', 'A row of carrels with no doors to the left and stacks on the right.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/hatcher-south-open-carrels', null, true),
  ('international-studies-reading-room', 'harlan-h-hatcher-graduate-library', 'International Studies Reading Room', 'A small, tucked away reading room for individual or group study near the Hatcher North lobby.', 'The International Studies Reading Room is a smaller space with movable tables and chairs, as well as a pair of armchairs with a side table. The room has tall ceilings and natural light from west-facing windows.

To find this tucked away spot, start in the Hatcher North lobby and go towards the women''s restroom and elevators. Look for the International Studies sign and door to your left. You can also get to the room from the west stairwell (door number 110).

Keep in mind this room is shared with International Studies library staff and is next to their suite of offices with walls that do not reach to the ceiling.', null, null, 'low_noise'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/international-studies-rr1_edited_Z2pdwv6.webp', 'Open room with high ceilings, large pane windows, and tables with movable chairs.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/international-studies-reading-room', null, true),
  ('music-library-carrels', 'earl-v-moore-building', 'Music Library Carrels', 'Intended for advanced research and writing.', 'There are 20 reservable carrels with desks and lighting available for reading or writing on floor 4 of the Music Library.

We give priority to graduate students who are writing dissertations or for publication. Up to 3 people may share a carrel, each with an assigned shelf.

For more information on reserving a carrel, visit the Music Library Information Services Desk or send us an email at music.library@umich.edu.', null, null, 'quiet'::public.noise_level, '{bookable}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Music-Carrels-Sept2022-1185x790_edited_3ohCP.webp', 'View from behind of sitting in a carrel in the Music Library with scores on the shelf in front of them.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/music-library-carrels', null, true),
  ('music-library-floors-3-and-4', 'earl-v-moore-building', 'Music Library Floors 3 and 4', 'A quiet airy space with tables with a mix of seating for individuals and groups.', 'Quiet study spaces in the Music Library are one of the best kept secrets on campus. To keep these spaces clean, you can only have covered drinks and small snacks.

While the library spans 3 floors, all study space is on floors 3 and 4. Floor 3 has large windows on all sides that provide lots of natural light.', 3, 'Floors 3 and 4', 'quiet'::public.noise_level, '{natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/music-study2_edited_Z2peYTu.webp', 'View from the top of two floors with an opening in the middle. The ground floor has rectangular tables and low bookshelves, the top floor has a railing and armchairs.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/music-library-floors-3-and-4', null, true),
  ('shapiro-basement', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Basement Spaces', 'Movable tables and chairs in open areas, plus a CAEN Lab.', 'The Shapiro Basement is home to many rows of compact shelving, but there’s study space too!

The open areas — mostly near the main stairwell and elevators — have movable tables and chairs. The tables are in a variety of shapes for flexible configurations.

The opposite end of the floor has the Shapiro CAEN Lab, which offers computers and external monitors that you can plug your laptop into. Note that only eligible members of the Michigan Engineering community can access CAEN computers.

You’ll find movable whiteboards scattered throughout the floor and full whiteboard walls near the CAEN Lab.

The Student Parent and Caregiver Study Room is also located in the basement.', 0, 'Basement', 'low_noise'::public.noise_level, '{all_gender_restroom_on_floor,external_monitors,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Shapiro-Basement-Sep2022-1185x790_edited_Z2tbXp3.webp', 'Students studying at tables in the basement of the Shapiro Library', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/shapiro-basement', null, true),
  ('shapiro-bookable-study-rooms', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Bookable Study Rooms', 'Rooms for groups on the second and third floors with adjustable tables, rolling chairs, and whiteboards.', 'We have 14 bookable study rooms in the Shapiro Library: 12 on the second floor and 2 in the third floor Clark Commons. The rooms range in capacity from 4 to 9 people.

Each one has reconfigurable tables, rolling chairs, and a whiteboard. A selection of them have large displays and video conferencing technology.

You can reserve rooms up to 7 days in advance. They are not bookable Sunday through Thursday from 12am to 8am and are first come, first served instead.

Reserve a study room

See our bookable room and booth guidelines for information about reservation maximums, required check in, and clean up expectations.', null, null, 'conversational'::public.noise_level, '{bookable,natural_light,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/shapiro-group-study-exterior2_Z1WNUFf.webp', 'View into a hallway of group study rooms with windows on the upper half of the walls.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/shapiro-bookable-study-rooms', null, true),
  ('shapiro-floor-1', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Floor 1 Spaces', 'A large open area with a variety of seating options and tables, plus vending machines.', 'The open floor plan on floor 1 provides a combination of seating for groups and individuals. This is a Collaborative Zone and you can expect group work and socializing, along with people working alone.

Enter the floor through the glass doors beyond the information services desk in the Shapiro lobby. You’ll find low, cushioned bench seating that can be arranged to fit your needs, as well as armchairs and couches. On the left after entering the floor, there’s both Tech Shop Express and snack vending machines against the wall, as well as round tables with movable chairs. We also have a handful of study pods tucked next to the east window.

A large campus computing site with printing is in the center of the floor, and the remaining open area is filled with a mix of fixed and movable tables and chairs. There’s also a glass-enclosed area on the east wall with similar furniture. Most tables seat 1–4 people. There are movable whiteboards scattered throughout.

Floor 1 is also where you can find spaces that are part of the Shapiro Design Lab, including the PIE Space at the far south end of the floor that’s open for studying when not otherwise in use.', 1, 'Floor 1', 'conversational'::public.noise_level, '{wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/shapiro-floor1-5_2hFq4N.webp', 'A movable whiteboard and students working at tables on a big open floor.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/conversational-study-spaces/shapiro-floor-1', null, true),
  ('shapiro-floor-2', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Floor 2 Spaces', 'Rectangular tables and wooden chairs for working in groups or alone near others.', 'The main type of seating on floor 2 is large rectangular tables and wooden chairs. They fill an open area on the south end of the floor near large windows and additional groups of tables break up the rows of book stacks.

There is less natural light on the floor as you move from the open area toward the central stairs, but you’ll find a small selection of cushioned bench seating there among the leisure reading collection.

12 bookable study rooms are available in the southwest corner of the floor. There’s also a glassed-in Mac Lab campus computing site near the center of the floor.

This floor attracts a mixture of group study and individuals working alone, so the noise level varies.', 2, 'Floor 2', 'conversational'::public.noise_level, '{natural_light,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/shapiro-floor2-1_Z2qUdpg.webp', 'Students studying at long rectangular tables with a movable whiteboard in view and a window in the background.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/conversational-study-spaces/shapiro-floor-2', null, true),
  ('shapiro-floor-4', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Floor 4 Spaces', 'Table seating, mostly in windowed nooks, on a quieter floor that’s good for working alone.', 'The top floor of Shapiro has a mix of wooden tables and chairs throughout the floor. It is usually quieter than the other floors and is great for studying alone near others.

An open space on the north end of the floor near the elevators and Michigan Publishing offices is filled with round tables that are separated with privacy dividers into individual seats. There are also partitions throughout the space for privacy, a colorful wall mural, and a set of large windows in the center.

There are rectangular tables with seats for 2–6 people around the perimeter of the rest of the floor, including at the ends of book stacks and next to the Computer and Video Game Archive. Most are in floor-to-ceiling windowed nooks.', 4, 'Floor 4', 'low_noise'::public.noise_level, '{all_gender_restroom_on_floor,natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/shapiro-floor4-2_Z2rh6iL.webp', 'Round tables separated by partitions into individual work areas with windows in the background.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/low-noise-study-spaces/shapiro-floor-4', null, true),
  ('shapiro-reading-room', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Reading Room', 'Long tables with padded chairs and a mix of other seating, all for individual, focused study.', 'The Shapiro Reading Room at the south end of the Clark Commons is a space for quiet, focused, individual study. A large window in the center of the room and two on either side let in lots of natural light.

The room’s seating is primarily at long tables that seat up to 8 people at padded chairs. These tables are perpendicular to a windowed wall between the room and the rest of the Clark Commons. Each table has a pair of lamps for customizable lighting.

Along the exterior walls, there’s a selection of smaller tables and padded chairs, as well as armchairs and movable side tables. There are also two large counter-height tables with a lamp and seats for up to 4 people.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Clark%20Commons%20-%20Shapiro%20Reading%20Room-1_edited_Z1YqMJd.webp', 'Students studying at long tables in the Shapiro Reading Room with a sunbeam coming through the window', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/shapiro-reading-room', null, true),
  ('soundproof-booths', 'harold-t-and-vivian-b-shapiro-library', 'Soundproof Booths', 'Reservable booths for sound privacy.', 'Conduct your video or phone call in a soundproof booth without interruption or disrupting those around you.

Two individual booths and one accessible booth are available in the Clark Commons on floor 3 of the Shapiro Library.

One individual booth is available in the floor 1 space of the Shapiro Library. It will be on your right after entering the space through the glass doors.

Booths can be reserved up to 7 days in advance and are open for use when not reserved.

Reserve a soundproof booth

See our bookable room and booth guidelines for information about reservation maximums, required check in, and clean up expectations.', null, null, 'quiet'::public.noise_level, '{all_gender_restroom_on_floor,bookable}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Clark%20Commons%20-%20Soundproof%20Booth%201_edited_ZhMaYb.webp', 'Student seated inside a tall soundproof booth with a transparent door', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/bookable-study-spaces/soundproof-booths', null, true),
  ('student-parent-and-caregiver-study-room', 'harold-t-and-vivian-b-shapiro-library', 'Student Parent and Caregiver Study Room', 'A study room for student parents and caregivers.', 'This child-friendly space, located close to elevators and restrooms, is an environment where student parents and caregivers can get work done while accompanied by the ones they care for.

Access to the room is available by keycode only to members of Michigan Caregivers and Student Parents (MCaSP).

For more information or to join the group, email studentparents@umich.edu.', null, null, 'conversational'::public.noise_level, '{all_gender_restroom_on_floor,wheelchair_accessible,whiteboards}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Shapiro%20-%20Student%20Parent%20Caregiver%20Study%20Room-2_edited_e0dbe.webp', 'A wall with a jungle mural, high back chairs, child-size desk, little free library lending book shelves, and table with a shared display.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/student-parent-and-caregiver-study-room', null, true),
  ('taubman-health-sciences-library-study-space', 'alfred-a-taubman-health-sciences-library', 'Taubman Health Sciences Library Study Space', 'A wide variety of seating options, plus computing, in a light-filled space for focused work.', 'The Taubman Health Sciences Library is a distinct space located within the broader building. Enter the library through the double-glass doors off the lobby to find this mixed seating study area. The space is generally quiet, but you’ll notice some noise with the doors opening and closing and people walking through.

Extended hours are available for medical students and graduate students from dentistry, kinesiology, nursing, pharmacy, public health, and social work. Use MCard for entry.', null, null, 'quiet'::public.noise_level, '{external_monitors,natural_light,wheelchair_accessible}'::public.space_feature[], null, 'https://www.lib.umich.edu/_astro/Taubman-Study1-Sept2019_Zp6Rea.webp', 'Open and deep space full of students working.', 'um_library'::public.space_source, 'https://www.lib.umich.edu/visit-and-study/study-spaces/quiet-study-spaces/taubman-health-sciences-library-study-space', null, true),
  ('shapiro-library-1f', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Library — 1st Floor', null, null, 1, '1st Floor', 'quiet'::public.noise_level, '{outlets,printing,scanners}'::public.space_feature[], 120, null, null, 'mguide'::public.space_source, null, 'shapiro-1', false),
  ('shapiro-library-2f', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Library — 2nd Floor', null, null, 2, '2nd Floor', 'low_noise'::public.noise_level, '{group_rooms,outlets,whiteboards}'::public.space_feature[], 80, null, null, 'mguide'::public.space_source, null, 'shapiro-2', false),
  ('shapiro-library-basement', 'harold-t-and-vivian-b-shapiro-library', 'Shapiro Library — Basement (UGLI)', null, null, 0, 'Basement', 'conversational'::public.noise_level, '{computers,group_rooms,outlets,printing}'::public.space_feature[], 200, null, null, 'mguide'::public.space_source, null, 'ugli-basement', false),
